20	import java.util.function.Function;
21	
22	/**
23	 * Wraps a TensorFlow node and produces the respective Vespa tensor operation.
24	 * During import, a graph of these operations are constructed. Then, the
25	 * types are used to deduce sensible dimension names using the
26	 * DimensionRenamer. After the types have been renamed, the proper
27	 * Vespa expressions can be extracted.
28	 *
29	 * @author lesters
30	 */
31	public abstract class TensorFlowOperation {
32	
33	    protected final static String MACRO_PREFIX = "tf_macro_";
34	
35	    protected final NodeDef node;
36	    protected final int port;
37	    protected final List<TensorFlowOperation> inputs;
38	    protected final List<TensorFlowOperation> outputs = new ArrayList<>();
39	    protected final List<String> importWarnings = new ArrayList<>();
40	
41	    protected OrderedTensorType type;
42	    protected TensorFunction function;
43	    protected TensorFunction macro = null;
44	
45	    private Value constantValue = null;
46	    private List<TensorFlowOperation> controlInputs = Collections.emptyList();
47	
48	    TensorFlowOperation(NodeDef node, List<TensorFlowOperation> inputs, int port) {
49	        this.node = node;
50	        this.port = port;
51	        this.inputs = Collections.unmodifiableList(inputs);
52	        this.inputs.forEach(i -> i.outputs.add(this));
53	    }
54	
55	    protected abstract OrderedTensorType lazyGetType();
56	    protected abstract TensorFunction lazyGetFunction();
57	
58	    /** Returns the Vespa tensor type of this operation if it exists */
59	    public Optional<OrderedTensorType> type() {
60	        if (type == null) {
61	            type = lazyGetType();
62	        }
63	        if (type != null) {
64	            type.verifyType(node);
65	        }
66	        return Optional.ofNullable(type);
67	    }
68	
69	    /** Returns the Vespa tensor function implementing all operations from this node with inputs */
70	    public Optional<TensorFunction> function() {
71	        if (function == null) {
72	            if (isConstant()) {
73	                ExpressionNode constant = new ReferenceNode(Reference.simple("constant", vespaName()));
74	                function = new TensorFunctionNode.TensorFunctionExpressionNode(constant);
75	            } else if (outputs.size() > 1) {
76	                macro = lazyGetFunction();
77	                function = new VariableTensor(macroName(), type.type());
78	            } else {
79	                function = lazyGetFunction();
80	            }
81	        }
82	        return Optional.ofNullable(function);
83	    }
84	
85	    /** Return TensorFlow node */
86	    public NodeDef node() { return node; }
87	
88	    /** Return unmodifiable list of inputs */
89	    public List<TensorFlowOperation> inputs() { return inputs; }
90	
91	    /** Return unmodifiable list of outputs. If a node has multiple outputs, consider adding a macro. */
92	    public List<TensorFlowOperation> outputs() { return Collections.unmodifiableList(outputs); }
93	
94	    /** Returns a Vespa ranking expression that should be added as a macro */
95	    public Optional<TensorFunction> macro() { return Optional.ofNullable(macro); }
96	
97	    /** Add dimension name constraints for this operation */
98	    public void addDimensionNameConstraints(DimensionRenamer renamer) { }
99	
100	    /** Performs dimension rename for this operation */
101	    public void renameDimensions(DimensionRenamer renamer) { type = type.rename(renamer); }
102	
103	    /** Return true for operations that are inputs to the model itself (as opposed to inputs to the operation) */
104	    public boolean isInput() { return false; }
105	
106	    /** Return true if this node is constant */
107	    public boolean isConstant() { return inputs.stream().allMatch(TensorFlowOperation::isConstant); }
108	
109	    /** Sets the constant value */
110	    public void setConstantValue(Value value) { constantValue = value; }
111	
112	    /** Gets the constant value if it exists */
113	    public Optional<Value> getConstantValue() { return Optional.ofNullable(constantValue); }
114	
115	    /** Sets the external control inputs */
116	    public void setControlInputs(List<TensorFlowOperation> inputs) { this.controlInputs = inputs; }
117	
118	    /** Retrieve the control inputs for this operation */
119	    public List<TensorFlowOperation> getControlInputs() { return Collections.unmodifiableList(this.controlInputs); }
120	
121	    /** Retrieve the valid Vespa name of this node */
122	    public String vespaName() { return node.getName() != null ? node.getName().replace('/', '_') : null; }
123	
124	    /** Retrieve the valid Vespa name of this node if it is a macro */
125	    public String macroName() { return vespaName() != null ? MACRO_PREFIX + vespaName() : null; }
126	
127	    /** Retrieve the list of warnings produced during its lifetime */
128	    public List<String> warnings() { return Collections.unmodifiableList(importWarnings); }
129	
130	    boolean verifyInputs(int expected, Function<TensorFlowOperation, Optional<?>> func) {
131	        if (!controlInputs.stream().map(func).allMatch(Optional::isPresent)) {
132	            return false;
133	        }
134	        if (inputs.size() != expected) {
135	            throw new IllegalArgumentException("Expected " + expected + " inputs " +
136	                                               "for '" + node.getName() + "', got " + inputs.size());
137	        }
138	        return inputs.stream().map(func).allMatch(Optional::isPresent);
139	    }
140	
141	    boolean allInputTypesPresent(int expected) {
142	        return verifyInputs(expected, TensorFlowOperation::type);
143	    }
144	
145	    boolean allInputFunctionsPresent(int expected) {
146	        return verifyInputs(expected, TensorFlowOperation::function);
147	    }
148	
149	}
