2	package com.yahoo.searchlib.rankingexpression.integration.tensorflow.importer;
3	
4	import com.yahoo.tensor.TensorType;
5	import com.yahoo.tensor.TensorTypeParser;
6	import org.tensorflow.framework.AttrValue;
7	import org.tensorflow.framework.NodeDef;
8	import org.tensorflow.framework.TensorShapeProto;
9	
10	import java.util.ArrayList;
11	import java.util.Collections;
12	import java.util.List;
13	import java.util.Optional;
14	import java.util.stream.Collectors;
15	
16	/**
17	 * A Vespa tensor type is ordered by the lexicographical ordering of dimension
18	 * names. TensorFlow tensors have an explicit ordering of their dimensions.
19	 * During import, we need to track the Vespa dimension that matches the
20	 * corresponding TensorFlow dimension as the ordering can change after
21	 * dimension renaming. That is the purpose of this class.
22	 *
23	 * @author lesters
24	 */
25	public class OrderedTensorType {
26	
27	    private final TensorType type;
28	    private final List<TensorType.Dimension> dimensions;
29	
30	    private final long[] innerSizesTensorFlow;
31	    private final long[] innerSizesVespa;
32	    private final int[] dimensionMap;
33	
34	    private OrderedTensorType(List<TensorType.Dimension> dimensions) {
35	        this.dimensions = Collections.unmodifiableList(dimensions);
36	        this.type = new TensorType.Builder(dimensions).build();
37	        this.innerSizesTensorFlow = new long[dimensions.size()];
38	        this.innerSizesVespa = new long[dimensions.size()];
39	        this.dimensionMap = createDimensionMap();
40	    }
41	
42	    public TensorType type() {
43	        return this.type;
44	    }
45	
46	    public int rank() { return dimensions.size(); }
47	
48	    public List<TensorType.Dimension> dimensions() {
49	        return dimensions;
50	    }
51	
52	    public List<String> dimensionNames() {
53	        return dimensions.stream().map(TensorType.Dimension::name).collect(Collectors.toList());
54	    }
55	
56	    private int[] createDimensionMap() {
57	        int numDimensions = dimensions.size();
58	        if (numDimensions == 0) {
59	            return null;
60	        }
61	        innerSizesTensorFlow[numDimensions - 1] = 1;
62	        innerSizesVespa[numDimensions - 1] = 1;
63	        for (int i = numDimensions - 1; --i >= 0; ) {
64	            innerSizesTensorFlow[i] = dimensions().get(i+1).size().orElse(-1L) * innerSizesTensorFlow[i+1];
65	            innerSizesVespa[i] = type.dimensions().get(i+1).size().orElse(-1L) * innerSizesVespa[i+1];
66	        }
67	        int[] mapping = new int[numDimensions];
68	        for (int i = 0; i < numDimensions; ++i) {
69	            TensorType.Dimension dim1 = dimensions().get(i);
70	            for (int j = 0; j < numDimensions; ++j) {
71	                TensorType.Dimension dim2 = type.dimensions().get(j);
72	                if (dim1.equals(dim2)) {
73	                    mapping[i] = j;
74	                    break;
75	                }
76	            }
77	        }
78	        return mapping;
79	    }
80	
81	    /**
82	     * When dimension ordering between Vespa and TensorFlow differs, i.e.
83	     * after dimension renaming, use the dimension map to read in values
84	     * so that they are correctly laid out in memory for Vespa.
85	     * Used when importing tensors from TensorFlow.
86	     */
87	    public int toDirectIndex(int index) {
88	        if (dimensions.size() == 0) {
89	            return 0;
90	        }
91	        if (dimensionMap == null)  {
92	            throw new IllegalArgumentException("Dimension map is not available");
93	        }
94	        int directIndex = 0;
95	        long rest = index;
96	        for (int i = 0; i < dimensions.size(); ++i) {
97	            long address = rest / innerSizesTensorFlow[i];
98	            directIndex += innerSizesVespa[dimensionMap[i]] * address;
99	            rest %= innerSizesTensorFlow[i];
100	        }
101	        return directIndex;
102	    }
103	
104	    @Override
105	    public boolean equals(Object obj) {
106	        if (obj == null || !(obj instanceof OrderedTensorType)) {
107	            return false;
108	        }
109	        OrderedTensorType other = (OrderedTensorType) obj;
110	        if (dimensions.size() != dimensions.size()) {
111	            return false;
112	        }
113	        List<TensorType.Dimension> thisDimensions = this.dimensions();
114	        List<TensorType.Dimension> otherDimensions = other.dimensions();
115	        for (int i = 0; i < thisDimensions.size(); ++i) {
116	            if (!thisDimensions.get(i).equals(otherDimensions.get(i))) {
117	                return false;
118	            }
119	        }
120	        return true;
121	    }
122	
123	    public void verifyType(NodeDef node) {
124	        TensorShapeProto shape = tensorFlowShape(node);
125	        if (shape != null) {
126	            if (shape.getDimCount() != type.rank()) {
127	                throw new IllegalArgumentException("TensorFlow shape of '" + node.getName() + "' " +
128	                                                   "does not match Vespa shape");
129	            }
130	            for (int tensorFlowIndex = 0; tensorFlowIndex < dimensions.size(); ++tensorFlowIndex) {
131	                int vespaIndex = dimensionMap[tensorFlowIndex];
132	                TensorShapeProto.Dim tensorFlowDimension = shape.getDim(tensorFlowIndex);
133	                TensorType.Dimension vespaDimension = type().dimensions().get(vespaIndex);
134	                if (tensorFlowDimension.getSize() != vespaDimension.size().orElse(-1L)) {
135	                    throw new IllegalArgumentException("TensorFlow dimensions of '" + node.getName() + "' " +
136	                                                       "does not match Vespa dimensions");
137	                }
138	            }
139	        }
140	    }
141	
142	    private static TensorShapeProto tensorFlowShape(NodeDef node) {
143	        AttrValue attrValueList = node.getAttrMap().get("_output_shapes");
144	        if (attrValueList == null) {
145	            throw new IllegalArgumentException("_output_shapes attribute of '" + node.getName() + "' " +
146	                                               "does not exist");
147	        }
148	        if (attrValueList.getValueCase() != AttrValue.ValueCase.LIST) {
149	            throw new IllegalArgumentException("_output_shapes attribute of '" + node.getName() + "' " +
150	                                               "is not of expected type");
151	        }
152	        List<TensorShapeProto> shapeList = attrValueList.getList().getShapeList();
153	        return shapeList.get(0); // support multiple outputs?
154	    }
155	
156	    public OrderedTensorType rename(DimensionRenamer renamer) {
157	        List<TensorType.Dimension> renamedDimensions = new ArrayList<>(dimensions.size());
158	        for (TensorType.Dimension dimension : dimensions) {
159	            String oldName = dimension.name();
160	            Optional<String> newName = renamer.dimensionNameOf(oldName);
161	            if (!newName.isPresent())
162	                return this; // presumably, already renamed
163	            TensorType.Dimension.Type dimensionType = dimension.type();
164	            if (dimensionType == TensorType.Dimension.Type.indexedBound) {
165	                renamedDimensions.add(TensorType.Dimension.indexed(newName.get(), dimension.size().get()));
166	            } else if (dimensionType == TensorType.Dimension.Type.indexedUnbound) {
167	                renamedDimensions.add(TensorType.Dimension.indexed(newName.get()));
168	            } else if (dimensionType == TensorType.Dimension.Type.mapped) {
169	                renamedDimensions.add(TensorType.Dimension.mapped(newName.get()));
170	            }
171	        }
172	        return new OrderedTensorType(renamedDimensions);
173	    }
