24	public class Mean extends TensorFlowOperation {
25	
26	    private List<String> reduceDimensions;
27	
28	    public Mean(NodeDef node, List<TensorFlowOperation> inputs, int port) {
29	        super(node, inputs, port);
30	    }
31	
32	    @Override
33	    protected OrderedTensorType lazyGetType() {
34	        if (!allInputTypesPresent(2)) {
35	            return null;
36	        }
37	        TensorFlowOperation reductionIndices = inputs.get(1);
38	        if (!reductionIndices.getConstantValue().isPresent()) {
39	            throw new IllegalArgumentException("Mean in " + node.getName() + ": " +
40	                    "reduction indices must be a constant.");
41	        }
42	        Tensor indices = reductionIndices.getConstantValue().get().asTensor();
43	        reduceDimensions = new ArrayList<>();
44	
45	        OrderedTensorType inputType = inputs.get(0).type().get();
46	        for (Iterator<Tensor.Cell> cellIterator = indices.cellIterator(); cellIterator.hasNext();) {
47	            Tensor.Cell cell = cellIterator.next();
48	            int dimensionIndex = cell.getValue().intValue();
49	            if (dimensionIndex < 0) {
50	                dimensionIndex = inputType.dimensions().size() - dimensionIndex;
51	            }
52	            reduceDimensions.add(inputType.dimensions().get(dimensionIndex).name());
53	        }
54	        return reducedType(inputType, shouldKeepDimensions());
55	    }
56	
57	    // todo: optimization: if keepDims and one reduce dimension that has size 1: same as identity.
58	
59	    @Override
60	    protected TensorFunction lazyGetFunction() {
61	        if (!allInputTypesPresent(2)) {
62	            return null;
63	        }
64	        TensorFunction inputFunction = inputs.get(0).function().get();
65	        TensorFunction output = new Reduce(inputFunction, Reduce.Aggregator.avg, reduceDimensions);
66	        if (shouldKeepDimensions()) {
67	            // multiply with a generated tensor created from the reduced dimensions
68	            TensorType.Builder typeBuilder = new TensorType.Builder();
69	            for (String name : reduceDimensions) {
70	                typeBuilder.indexed(name, 1);
71	            }
72	            TensorType generatedType = typeBuilder.build();
73	            ExpressionNode generatedExpression = new ConstantNode(new DoubleValue(1));
74	            Generate generatedFunction = new Generate(generatedType,
75	                    new GeneratorLambdaFunctionNode(generatedType, generatedExpression).asLongListToDoubleOperator());
76	            output = new com.yahoo.tensor.functions.Join(output, generatedFunction, ScalarFunctions.multiply());
77	        }
78	        return output;
79	    }
80	
81	    @Override
82	    public void renameDimensions(DimensionRenamer renamer) {
83	        super.renameDimensions(renamer);
84	        List<String> renamedDimensions = new ArrayList<>(reduceDimensions.size());
85	        for (String name : reduceDimensions) {
86	            Optional<String> newName = renamer.dimensionNameOf(name);
87	            if (!newName.isPresent()) {
88	                return;  // presumably, already renamed
89	            }
90	            renamedDimensions.add(newName.get());
91	        }
92	        reduceDimensions = renamedDimensions;
93	    }
94	
95	    private boolean shouldKeepDimensions() {
96	        AttrValue keepDimsAttr = node.getAttrMap().get("keep_dims");
97	        return keepDimsAttr != null && keepDimsAttr.getB();
98	    }
99	
100	    private OrderedTensorType reducedType(OrderedTensorType inputType, boolean keepDimensions) {
101	        OrderedTensorType.Builder builder = new OrderedTensorType.Builder(node);
102	        for (TensorType.Dimension dimension: inputType.type().dimensions()) {
103	            if (!reduceDimensions.contains(dimension.name())) {
104	                builder.add(dimension);
105	            } else if (keepDimensions) {
106	                builder.add(TensorType.Dimension.indexed(dimension.name(), 1L));
107	            }
108	        }
109	        return builder.build();
110	    }
