9	
10	import java.util.List;
11	import java.util.Optional;
12	
13	public class Matmul extends TensorFlowOperation {
14	
15	    public Matmul(NodeDef node, List<TensorFlowOperation> inputs, int port) {
16	        super(node, inputs, port);
17	    }
18	
19	    @Override
20	    protected OrderedTensorType lazyGetType() {
21	        if (!allInputTypesPresent(2)) {
22	            return null;
23	        }
24	        OrderedTensorType.Builder typeBuilder = new OrderedTensorType.Builder(node);
25	        typeBuilder.add(inputs.get(0).type().get().dimensions().get(0));
26	        typeBuilder.add(inputs.get(1).type().get().dimensions().get(1));
27	        return typeBuilder.build();
28	    }
29	
30	    @Override
31	    protected TensorFunction lazyGetFunction() {
32	        if (!allInputTypesPresent(2)) {
33	            return null;
34	        }
35	        OrderedTensorType aType = inputs.get(0).type().get();
36	        OrderedTensorType bType = inputs.get(1).type().get();
37	        if (aType.type().rank() < 2 || bType.type().rank() < 2)
38	            throw new IllegalArgumentException("Tensors in matmul must have rank of at least 2");
39	        if (aType.type().rank() != bType.type().rank())
40	            throw new IllegalArgumentException("Tensors in matmul must have the same rank");
41	
42	        Optional<TensorFunction> aFunction = inputs.get(0).function();
43	        Optional<TensorFunction> bFunction = inputs.get(1).function();
44	        if (!aFunction.isPresent() || !bFunction.isPresent()) {
45	            return null;
46	        }
47	        return new com.yahoo.tensor.functions.Matmul(aFunction.get(), bFunction.get(), aType.dimensions().get(1).name());
48	    }
49	
50	    @Override
51	    public void addDimensionNameConstraints(DimensionRenamer renamer) {
52	        if (!allInputTypesPresent(2)) {
53	            return;
54	        }
55	        List<TensorType.Dimension> aDimensions = inputs.get(0).type().get().dimensions();
56	        List<TensorType.Dimension> bDimensions = inputs.get(1).type().get().dimensions();
57	
58	        String aDim0 = aDimensions.get(0).name();
59	        String aDim1 = aDimensions.get(1).name();
60	        String bDim0 = bDimensions.get(0).name();
61	        String bDim1 = bDimensions.get(1).name();
62	
63	        // The second dimension of a should have the same name as the first dimension of b
64	        renamer.addConstraint(aDim1, bDim0, DimensionRenamer::equals, this);
65	
66	        // The first dimension of a should have a different name than the second dimension of b
67	        renamer.addConstraint(aDim0, bDim1, DimensionRenamer::lesserThan, this);
68	
69	        // For efficiency, the dimensions to join over should be innermost - soft constraint
70	        renamer.addConstraint(aDim0, aDim1, DimensionRenamer::lesserThan, this);
71	        renamer.addConstraint(bDim0, bDim1, DimensionRenamer::greaterThan, this);
72	    }
73	
